import{_ as t,c as e,o,a7 as r}from"./chunks/framework.DPTpzYjp.js";const b=JSON.parse('{"title":"OrbitControl 的优势","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/introduction/advantage.md","filePath":"orbitcontrol/introduction/advantage.md"}'),n={name:"orbitcontrol/introduction/advantage.md"};function i(l,a,d,c,h,s){return o(),e("div",null,a[0]||(a[0]=[r('<h1 id="orbitcontrol-的优势" tabindex="-1">OrbitControl 的优势 <a class="header-anchor" href="#orbitcontrol-的优势" aria-label="Permalink to &quot;OrbitControl 的优势&quot;">​</a></h1><h2 id="以地图为中心的作业体验" tabindex="-1">以地图为中心的作业体验 <a class="header-anchor" href="#以地图为中心的作业体验" aria-label="Permalink to &quot;以地图为中心的作业体验&quot;">​</a></h2><p>建图、路网绘制、标注、任务编排全部在地图上完成，所见即所得；实况操控时设备位置与作业要素同屏呈现，降低操作员的空间认知负担。</p><h2 id="一屏完成实时操控" tabindex="-1">一屏完成实时操控 <a class="header-anchor" href="#一屏完成实时操控" aria-label="Permalink to &quot;一屏完成实时操控&quot;">​</a></h2><p>设备控制台集成第一视角画面、控制面板与虚拟摇杆，单界面覆盖设备常用操控；视频墙支持多设备画面同屏轮巡，适合值守场景。</p><h2 id="从手动到无人值守的调度梯度" tabindex="-1">从手动到无人值守的调度梯度 <a class="header-anchor" href="#从手动到无人值守的调度梯度" aria-label="Permalink to &quot;从手动到无人值守的调度梯度&quot;">​</a></h2><p>同一个任务可以手动触发，也可以交给计划按时间表调度，或由自动化流程按事件联动触发——按作业成熟度逐步放手，无需更换平台。</p><h2 id="全程可追溯" tabindex="-1">全程可追溯 <a class="header-anchor" href="#全程可追溯" aria-label="Permalink to &quot;全程可追溯&quot;">​</a></h2><p>每次执行自动产出运行日志、现场媒体（画廊）与过程录屏（回放），作业结果有据可查，异常可回放定位。</p><h2 id="多企业与角色权限" tabindex="-1">多企业与角色权限 <a class="header-anchor" href="#多企业与角色权限" aria-label="Permalink to &quot;多企业与角色权限&quot;">​</a></h2><p>企业之间资源完全隔离；企业内按角色分配功能权限，管理员与操作员各司其职。</p><h2 id="开放的集成能力" tabindex="-1">开放的集成能力 <a class="header-anchor" href="#开放的集成能力" aria-label="Permalink to &quot;开放的集成能力&quot;">​</a></h2><p>设备端采用开放的 MQTT 协议规范，平台侧提供应用集成（Access Token），第三方系统可以对接平台的设备状态与作业数据。</p>',13)]))}const u=t(n,[["render",i]]);export{b as __pageData,u as default};
